template<int RT> struct mint {
	static constexpr mint rt() { return RT; }
	int v; explicit operator int() const { return v; }
	mint() { v = 0; }
	mint(ll _v) { v = int((-MOD < _v && _v < MOD) ? _v : _v % MOD);
